// Requires the IAM action emailExchange:apiovh:service/task/get.
func (s *Service) GetServiceTask(ctx context.Context, organizationName string, exchangeService string, id int) (*EmailExchangeTask, error) {
	return ovh.Call[*EmailExchangeTask](ctx, s.c, &ovh.Request{Method: http.MethodGet, Path: ovh.Path("/v1/email/exchange/{organizationName}/service/{exchangeService}/task/{id}", "organizationName", organizationName, "exchangeService", exchangeService, "id", id)})
}

// AllServiceTasks iterates over every object ListServiceTasks lists, fetching each one with
// GetServiceTask only when the loop reaches it. An object deleted in the meantime is skipped; on
// any other error it yields the error and stops.
func (s *Service) AllServiceTasks(ctx context.Context, organizationName string, exchangeService string) iter.Seq2[*EmailExchangeTask, error] {
	return ovh.Each(ctx,
		func(ctx context.Context) ([]int, error) {
			return s.ListServiceTasks(ctx, organizationName, exchangeService)
		},
		func(ctx context.Context, listedID int) (*EmailExchangeTask, error) {
			return s.GetServiceTask(ctx, organizationName, exchangeService, listedID)
		})
}

